Can_Rx can_rx_create (Can_Dev can_dev)
{
  CRITICAL ;

  Can_Rx can_rx = (Can_Rx) os_mem_request (sizeof (struct s_Can_Rx)) ;

  can_rx->can_dev      = can_dev          ;
  can_rx->irq_rx_ready = os_irq_create () ;

  C_ENTER ;
    {
      can_dev->rx[0] = can_rx  ;
    }
  C_LEAVE ;

  return can_rx  ;
}

